const nav = document.querySelectorAll('.admin-nav button');
const title = document.querySelector('.admin-heading h1');
const desc = document.querySelector('.admin-heading p');
const toast = document.querySelector('.toast');
const showToast = message => { toast.textContent = message; toast.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => toast.classList.remove('show'), 2400); };
nav.forEach(item => item.addEventListener('click', () => { nav.forEach(n => n.classList.remove('active')); item.classList.add('active'); const label = item.dataset.label || item.textContent.trim(); title.textContent = label; desc.textContent = label === 'Overview' ? 'A live pulse check across your gym operations.' : `${label} module preview — ready to connect to the gym CRM.`; showToast(`${label} module selected`); }));
document.querySelector('.admin-mobile-toggle')?.addEventListener('click', () => document.querySelector('.admin-sidebar').classList.toggle('open'));
document.querySelector('.admin-icon[data-notify]')?.addEventListener('click', () => showToast('You have 3 renewal reminders to review.'));
const search = document.querySelector('#memberSearch'); const statusFilter = document.querySelector('#statusFilter');
const filterRows = () => { const q = search.value.toLowerCase(); const status = statusFilter.value; document.querySelectorAll('.member-row').forEach(row => { const matchesText = row.textContent.toLowerCase().includes(q); const matchesStatus = !status || row.dataset.status === status; row.style.display = matchesText && matchesStatus ? '' : 'none'; }); };
search?.addEventListener('input', filterRows); statusFilter?.addEventListener('change', filterRows);
const backdrop = document.querySelector('.modal-backdrop'); const closeModal = () => backdrop.classList.remove('open');
document.querySelector('#addMemberBtn')?.addEventListener('click', () => { document.querySelector('#memberModal').classList.add('open'); document.querySelector('#memberName')?.focus(); });
document.querySelectorAll('[data-close-modal]').forEach(b => b.addEventListener('click', closeModal)); backdrop?.addEventListener('click', e => { if(e.target === backdrop) closeModal(); });
document.querySelector('#memberForm')?.addEventListener('submit', e => { e.preventDefault(); const name = document.querySelector('#memberName').value; const plan = document.querySelector('#memberPlan').value; const initials = name.split(' ').map(x => x[0]).join('').slice(0,2).toUpperCase(); const row = document.createElement('tr'); row.className = 'member-row'; row.dataset.status = 'active'; row.innerHTML = `<td><div class="member-name"><span class="avatar">${initials}</span><div><strong>${name}</strong><span>TMG-${Math.floor(1000 + Math.random()*9000)}</span></div></div></td><td>${plan}</td><td>16 Oct 2026</td><td><span class="status active">Active</span></td><td>₹0</td><td><button class="row-action">⋯</button></td>`; document.querySelector('#memberTableBody').prepend(row); closeModal(); e.target.reset(); showToast(`${name} added to members.`); });
document.querySelector('#exportBtn')?.addEventListener('click', () => { const rows = [['Member','Plan','Joined','Status','Pending dues'], ...Array.from(document.querySelectorAll('.member-row')).filter(r => r.style.display !== 'none').map(r => Array.from(r.querySelectorAll('td')).slice(0,5).map(td => td.innerText.replace(/\n/g,' ')))]; const csv = rows.map(row => row.map(cell => `"${cell.replaceAll('"','""')}"`).join(',')).join('\n'); const blob = new Blob([csv],{type:'text/csv'}); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'mission-gym-members.csv'; link.click(); URL.revokeObjectURL(link.href); showToast('Member report exported.'); });
document.querySelectorAll('.row-action').forEach(btn => btn.addEventListener('click', () => { const row = btn.closest('tr'); document.querySelector('#detailName').textContent = row.querySelector('.member-name strong').textContent; document.querySelector('#detailPlan').textContent = row.children[1].textContent; document.querySelector('#detailModal').classList.add('open'); }));
document.querySelector('#detailModal [data-close-modal]')?.addEventListener('click', closeModal);
